# This file is automatically generated from traits.build
# package, via the file build_targets.whisker:
# edit the file there (or the files that it includes).
#
# ---------------------------------------------------------------------------
# Using this pipeline: three steps, not one
#
#   # 1. rebuild the compilation
#   targets::tar_make()
#
#   # 2. load the result into your session
#   austraits <- targets::tar_read(austraits)
#
#   # 3. write export/data/curr, when you want to publish
#   build_export("austraits")
#
# Step 2 is separate because `tar_make()` returns nothing: it builds into the
# `_targets/` store and prints what it did. `remake::make()` returned the
# database, so the direct translation of that habit --
# `austraits <- targets::tar_make("austraits")` -- leaves you holding NULL.
#
# Step 3 is separate because writing the exported .rds is about a third of a
# one-dataset rebuild, and is a publishing step rather than part of checking a
# dataset. `tar_make()` therefore leaves `export/data/curr` alone. Pass
# `build_export()` the same `database_name` this file was generated with.
#
# On output: `tar_make()` prints two lines per target -- several hundred lines
# on a large compilation -- in the order its scheduler reaches them rather than
# alphabetically. Neither is adjustable: `targets` collapses only dynamic
# branches into a progress bar, and it deprecated target priorities in 1.10.1
# when it moved to the current scheduler, so execution order is no longer
# controllable. To build quietly:
#
#   targets::tar_make(reporter = "silent")
#
# or, once for the repository, `targets::tar_config_set(reporter_make = "silent")`.
# ---------------------------------------------------------------------------

